import '../quiz/quiz_grader.dart';

/// The learning rules, as pure functions. They mirror backend/app/learning/rules.py
/// and state.py; test/learning_vectors.json (generated by the backend) keeps
/// them identical on both sides.
///
/// General test (when the server has it switched on): the General PRE-test is
/// taken once before any module opens; the General POST-test (same questions)
/// opens once every module is completed, and is also taken once.
///
/// A module can be completed when it is unlocked and
///   1. its inline True/False quiz, if it has one, has been passed: one attempt
///      at the [kQuizPassMark] (90%) pass mark, exact arithmetic (three
///      statements need all three right). Retakes are unlimited until the
///      module is completed;
///   2. at least the minimum active time (the server's module_min_seconds,
///      [kDefaultModuleMinSeconds] until the phone has it) was spent in it.
/// Completing a module unlocks the next one. A completed module stays
/// completed and is review-only.

/// Default minimum active time per module, until GET /sync/learning says otherwise.
const kDefaultModuleMinSeconds = 180;

bool moduleQuizPasses(int correct, int total) => quizPassed(correct, total);

bool canCompleteModule({
  required bool unlocked,
  required bool hasQuiz,
  required bool quizPassed,
  required int seconds,
  required int minSeconds,
}) =>
    unlocked && (!hasQuiz || quizPassed) && seconds >= minSeconds;

enum ModuleStage { locked, reading, completed }

class TestScore {
  final String clientId;
  final String testType; // MODULE_QUIZ, or PRE/POST for the General test
  final int correct;
  final int total;
  final DateTime takenAt;

  const TestScore({
    required this.clientId,
    required this.testType,
    required this.correct,
    required this.total,
    required this.takenAt,
  });

  int get percent => quizScorePercent(correct, total);
}

class ModuleLearning {
  final String moduleId;
  final int quizStatements;
  final List<TestScore> quizAttempts; // counted attempts, oldest first
  final bool completed;
  final bool readingDone;
  final int secondsSpent;
  final int minSeconds;
  final bool unlocked;
  /// Why it is locked: the General pre-test, or an earlier module.
  final bool lockedByGeneralTest;

  const ModuleLearning({
    required this.moduleId,
    required this.quizStatements,
    required this.quizAttempts,
    required this.completed,
    required this.readingDone,
    required this.secondsSpent,
    required this.minSeconds,
    required this.unlocked,
    this.lockedByGeneralTest = false,
  });

  bool get hasQuiz => quizStatements > 0;

  /// The first attempt that reached the pass mark, if any.
  TestScore? get passingQuiz {
    for (final a in quizAttempts) {
      if (moduleQuizPasses(a.correct, a.total)) return a;
    }
    return null;
  }

  bool get quizPassed => !hasQuiz || passingQuiz != null;
  bool get timeMet => secondsSpent >= minSeconds;
  int get secondsLeft => timeMet ? 0 : minSeconds - secondsSpent;

  ModuleStage get stage {
    if (completed) return ModuleStage.completed;
    if (!unlocked) return ModuleStage.locked;
    return ModuleStage.reading;
  }

  /// Reading and the quiz are open whenever the module is.
  bool get canRead => unlocked || completed;

  /// The quiz can be (re)taken until the module is completed.
  bool get canTakeQuiz => !completed && unlocked && hasQuiz;

  bool get canComplete =>
      !completed &&
      canCompleteModule(unlocked: unlocked, hasQuiz: hasQuiz, quizPassed: quizPassed, seconds: secondsSpent, minSeconds: minSeconds);
}

/// Per-module input for [computeLearning].
class ModuleInput {
  final String moduleId;
  final int quizStatements;
  final bool completed;
  final bool readingDone;
  final int secondsSpent;

  /// Module-quiz attempts that count (not rejected by the server).
  final List<TestScore> quizAttempts;

  const ModuleInput({
    required this.moduleId,
    this.quizStatements = 0,
    this.completed = false,
    this.readingDone = false,
    this.secondsSpent = 0,
    this.quizAttempts = const [],
  });
}

/// States for the learner's modules in learning order: a module is unlocked when
/// it is already completed, or when the General pre-test gate is open and every
/// earlier module is completed.
List<ModuleLearning> computeLearning(List<ModuleInput> modules,
    {int minSeconds = kDefaultModuleMinSeconds, bool gateOpen = true}) {
  final out = <ModuleLearning>[];
  var allBeforeDone = true;
  for (final m in modules) {
    final sorted = [...m.quizAttempts]..sort((a, b) => a.takenAt.compareTo(b.takenAt));
    final unlocked = m.completed || (gateOpen && allBeforeDone);
    out.add(ModuleLearning(
      moduleId: m.moduleId,
      quizStatements: m.quizStatements,
      quizAttempts: sorted,
      completed: m.completed,
      readingDone: m.readingDone,
      secondsSpent: m.secondsSpent,
      minSeconds: minSeconds,
      unlocked: unlocked,
      lockedByGeneralTest: !unlocked && !gateOpen,
    ));
    allBeforeDone = allBeforeDone && m.completed;
  }
  return out;
}

/// The learner's General pre-/post-test. Each test counts once: the first one.
class GeneralLearning {
  final bool active;
  final int questions;
  final TestScore? pre;
  final TestScore? post;
  final int modulesTotal;
  final int modulesCompleted;

  const GeneralLearning({
    required this.active,
    required this.questions,
    required this.pre,
    required this.post,
    required this.modulesTotal,
    required this.modulesCompleted,
  });

  bool get allModulesCompleted => modulesTotal > 0 && modulesCompleted == modulesTotal;

  /// Modules can open (the test is off, or the pre-test is taken).
  bool get gateOpen => !active || pre != null;

  bool get canTakePre => active && questions > 0 && pre == null;
  bool get canTakePost => active && questions > 0 && pre != null && post == null && allModulesCompleted;
}

/// The first counted General test of [testType] (PRE or POST), if any.
TestScore? firstOf(List<TestScore> attempts, String testType) {
  final mine = attempts.where((a) => a.testType == testType).toList()..sort((a, b) => a.takenAt.compareTo(b.takenAt));
  return mine.isEmpty ? null : mine.first;
}

// ---------- The retired per-module pre/post rule (2026-11) ----------
// Kept so older attempts read the same as on the server, and checked against the
// same shared vectors. It no longer decides anything on this phone.

/// Default auto-approval threshold (percent) for a 100% pre-test.
const kAutoApprovePercent = 90;

bool beats(int postCorrect, int postTotal, int preCorrect, int preTotal) =>
    postTotal > 0 && preTotal > 0 && postCorrect * preTotal > preCorrect * postTotal;

bool isPerfect(int correct, int total) => total > 0 && correct >= total;

/// Exact integer arithmetic, like the pass mark (no rounding at the edge).
bool reaches(int correct, int total, int percent) => total > 0 && correct * 100 >= percent * total;

bool postTestCompletes(int postCorrect, int postTotal, int preCorrect, int preTotal,
    {int autoApprovePercent = kAutoApprovePercent}) {
  if (isPerfect(preCorrect, preTotal)) return reaches(postCorrect, postTotal, autoApprovePercent);
  return quizPassed(postCorrect, postTotal) && beats(postCorrect, postTotal, preCorrect, preTotal);
}

/// Whether a learner may see a module: staff accounts see everything; a
/// learner sees General modules and those listing their learner role.
bool moduleVisibleTo({required String audience, required List<String> learnerRoles, required bool staff, String? learnerRole}) {
  if (staff || audience != 'ROLE_SPECIFIC') return true;
  return learnerRole != null && learnerRoles.contains(learnerRole);
}

const kLearnerRoleLabels = {
  'CDD': 'CDD',
  'HEALTH_WORKER': 'Health Worker',
  'LOGISTICIAN': 'Logistician',
  'MONITOR_SUPERVISOR': 'Monitor/Supervisor',
  'OTHER': 'Others',
};

/// "1:20" for 80 seconds.
String formatDuration(int seconds) {
  final s = seconds < 0 ? 0 : seconds;
  return '${s ~/ 60}:${(s % 60).toString().padLeft(2, '0')}';
}
